import{_ as d,o,c as t,a2 as c}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"MFM 语法","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/mfm.md","filePath":"guide/misskey/mfm.md","lastUpdated":1789295632000}'),a={name:"guide/misskey/mfm.md"};function r(s,e,n,i,p,l){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="mfm-语法" tabindex="-1">MFM 语法 <a class="header-anchor" href="#mfm-语法" aria-label="Permalink to &quot;MFM 语法&quot;">​</a></h1><p>MFM（Misskey Flavoured Markdown）是 Misskey 专属的富文本标记语言，可用于帖子、个人简介、频道描述等。输入框上方的「MFM」按钮可以快速插入常用语法。</p><h2 id="基础语法" tabindex="-1">基础语法 <a class="header-anchor" href="#基础语法" aria-label="Permalink to &quot;基础语法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>写法</th><th>效果</th></tr></thead><tbody><tr><td><code>**加粗**</code></td><td><strong>加粗</strong></td></tr><tr><td><code>*斜体*</code></td><td>斜体</td></tr><tr><td><code>~~删除线~~</code></td><td>删除线</td></tr><tr><td><code>`代码`</code></td><td>行内代码</td></tr><tr><td><code>&gt; 引用</code></td><td>引用块</td></tr><tr><td>```代码块```</td><td>多行代码</td></tr><tr><td><code>#话题</code></td><td>话题标签</td></tr><tr><td><code>@用户名</code></td><td>提及用户</td></tr><tr><td><code>:emoji:</code></td><td>自定义表情</td></tr><tr><td><code>[搜索]</code> 或内容后接 <code> search</code></td><td>搜索框</td></tr><tr><td><code>$[x2 内容]</code></td><td>放大两倍</td></tr></tbody></table><h2 id="动画与装饰" tabindex="-1">动画与装饰 <a class="header-anchor" href="#动画与装饰" aria-label="Permalink to &quot;动画与装饰&quot;">​</a></h2><p>MFM 支持 <code>$[标签 内容]</code> 格式的装饰语法，可叠加参数。当前支持的标签：</p><p><strong>动画类</strong>：<code>tada</code>（晃动强调）、<code>jelly</code>（果冻弹跳）、<code>twitch</code>（抽动）、<code>shake</code>（抖动）、<code>jump</code>（跳跃）、<code>bounce</code>（弹跳）、<code>spin</code>（旋转，支持 <code>left</code> / <code>alternate</code> / <code>x</code> / <code>y</code> 参数）</p><p><strong>缩放与位移</strong>：<code>x2</code> <code>x3</code> <code>x4</code>（放大）、<code>scale</code>（自定义缩放 <code>x=</code> <code>y=</code>）、<code>position</code>（位移 <code>x=</code> <code>y=</code>）、<code>rotate</code>（旋转 <code>deg=</code>）</p><p><strong>颜色与字体</strong>：<code>fg</code>（前景色 <code>color=</code>）、<code>bg</code>（背景色 <code>color=</code>）、<code>border</code>（边框）、<code>font</code>（字体：serif / monospace / cursive / fantasy / emoji / math）</p><p><strong>其他</strong>：<code>flip</code>（翻转 <code>h</code> / <code>v</code>）、<code>blur</code>（模糊，悬停显示）、<code>rainbow</code>（彩虹色）、<code>sparkle</code>（闪光）、<code>ruby</code>（注音）、<code>unixtime</code>（显示日期时间）、<code>tada</code> 等动画均支持 <code>speed=</code> 与 <code>delay=</code> 参数</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$[tada 🎉 庆祝]</span></span>\n<span class="line"><span>$[bg.color=ffcc00 黄底文字]</span></span>\n<span class="line"><span>$[spin.alternate 🌀]</span></span>\n<span class="line"><span>$[x2 $[rainbow 彩虹大字]]</span></span></code></pre></div><p>动画效果会在时间线中实际播放，善用可以让内容更生动，但也别过度使用，以免影响阅读。</p><p>更完整的语法说明见官方文档：<a href="https://misskey-hub.net/en/docs/for-users/features/mfm/" target="_blank" rel="noreferrer">MFM Cheatsheet</a>。</p>',14)])])}const f=d(a,[["render",r]]);export{m as __pageData,f as default};
